// WaitCondition Waits until the condition holds for the step target; on timeout the run ends as `error` (like a failed precondition).
type WaitCondition struct {
	// Destination Exactly one property. Omit the whole destination for "any".
	Destination *Destination `json:"destination,omitempty"`

	// For `connected` - a new connection matching the `TrafficMatch`; `dns_query` - a query for `name`.
	For WaitConditionFor `json:"for"`

	// Name Exact name or `*.suffix` (matches the suffix's subdomains, not the suffix itself).
	Name       *Hostname    `json:"name,omitempty"`
	PortRanges *[]PortRange `json:"port_ranges,omitempty"`
	Ports      *[]int       `json:"ports,omitempty"`
	Protocol   *Protocol    `json:"protocol,omitempty"`

	// Timeout Example: 90s
	Timeout Duration `json:"timeout"`
}

// WaitConditionFor `connected` - a new connection matching the `TrafficMatch`; `dns_query` - a query for `name`.
type WaitConditionFor string

// WireGuardAction WireGuard test action (plan §2.2.1, §2.2.2), lasting as long as the overlay:
// `disable` removes the peer from the interface ("peer offline", for a link "link
// down"); `key_mismatch` replaces the peer's public key on the gateway by a random one,
// as if a rotated key was not deployed; `block_endpoint` drops the peer's encrypted UDP.
// Requires M10.
type WireGuardAction struct {
	Action WireGuardActionAction `json:"action"`

	// Client UUID or name of an object. Stored configurations contain UUIDs only.
	Client *Ref `json:"client,omitempty"`

	// Link UUID or name of an object. Stored configurations contain UUIDs only.
	Link *Ref `json:"link,omitempty"`
}

// WireGuardActionAction defines model for WireGuardAction.Action.
type WireGuardActionAction string

// WireGuardClient A peer of a hub network. Each client is also a device with the same UUID and name (device namespace); there is no separate `Device` entry for it.
type WireGuardClient struct {
	// Address Tunnel address inside the hub's subnet.
	Address Ipv4 `json:"address"`

	// ClientNetworks Subnets behind the client (part of its AllowedIPs and routed via the hub).
	ClientNetworks *[]Ipv4Cidr  `json:"client_networks,omitempty"`
	Description    *Description `json:"description,omitempty"`

	// Dns DNS server written into the client's exported configuration.
	Dns *WireGuardClientDns `json:"dns,omitempty"`

	// Enabled Disabled clients are removed from the interface.
	Enabled   *bool                 `json:"enabled,omitempty"`
	Keepalive *Duration             `json:"keepalive,omitempty"`
	Key       *WireGuardKeySettings `json:"key,omitempty"`
	Labels    *[]string             `json:"labels,omitempty"`

	// Name Unique per object type (case-insensitive); must not have the form of a UUID.
	Name Name `json:"name"`

	// Reachable Networks the client may reach. They become the routes (AllowedIPs) of the exported
	// configuration and implicit `allow` entries from this client in the access matrix.
	// `{uplink: true}` means full tunnel (AllowedIPs 0.0.0.0/0).
	Reachable *[]MatrixEndpoint `json:"reachable,omitempty"`

	// TrustsTestCa As `Device.trusts_test_ca`.
	TrustsTestCa *bool `json:"trusts_test_ca,omitempty"`
}

