// AsLanNetwork returns the union data inside the Network as a LanNetwork
func (t Network) AsLanNetwork() (LanNetwork, error) {
	var body LanNetwork
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromLanNetwork overwrites any union data inside the Network as the provided LanNetwork
func (t *Network) FromLanNetwork(v LanNetwork) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"lan"}`))
	t.union = b
	return err
}

// MergeLanNetwork performs a merge with any union data inside the Network, using the provided LanNetwork
func (t *Network) MergeLanNetwork(v LanNetwork) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"type":"lan"}`))
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

// AsWireGuardNetwork returns the union data inside the Network as a WireGuardNetwork
func (t Network) AsWireGuardNetwork() (WireGuardNetwork, error) {
	var body WireGuardNetwork
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromWireGuardNetwork overwrites any union data inside the Network as the provided WireGuardNetwork
